INSERT [dbo].[AIJobDraftVersions] ([Id], [AIJobDraftId], [VersionNumber], [Title], [Description], [Objectives], [Scope], [UserStories], [RequiredSkills], [Deliverables], [Milestones], [Generator], [CreatedAtUtc], [ExternalAiRequested], [PromptVersion], [KnowledgeReferences]) VALUES (1, 1, 1, N'Báo cáo lịch hẹn và chất lượng phục vụ', N'Tổng hợp số lịch hẹn, tỷ lệ khách đến và nhu cầu theo khung giờ. Phạm vi giới hạn ở số liệu vận hành đã ẩn danh; đối chiếu số tổng trước khi bàn giao.

Cách phối hợp: thống nhất phạm vi qua đề xuất, xác nhận hợp đồng và ký quỹ từng mốc trước khi thực hiện. Cập nhật tiến độ hai lần mỗi tuần. Bàn giao kèm tài liệu, tệp nguồn và hướng dẫn sử dụng trong phạm vi đã chốt.', N'Theo dõi nhu cầu và điều phối khung giờ dựa trên số liệu vận hành.', N'Làm sạch dữ liệu lịch hẹn đã ẩn danh và xây báo cáo theo ngày, dịch vụ, cơ sở.', N'Quản lý xem được số lịch hẹn và tỷ lệ khách đến để bố trí nhân sự.', N'SQL, làm sạch dữ liệu, thiết kế dashboard', N'Báo cáo, bảng định nghĩa chỉ số, hướng dẫn cập nhật và đối chiếu số liệu.', N'Thống nhất chỉ số; bàn giao báo cáo và hướng dẫn.', N'Manual', CAST(N'2026-10-18T05:44:09.787' AS DateTime), 0, NULL, NULL)
GO
