INSERT [dbo].[ContractVersions] ([Id], [ContractId], [VersionNumber], [SnapshotJson], [Hash], [Price], [FeeRate], [DeliveryDays], [CreatedAtUtc]) VALUES (1, 1, 1, N'{"ProjectTitle":"Tích hợp quản lý đơn hàng cho Hương Việt Coffee","Scope":"Triển khai API quản lý đơn và trạng thái giao hàng, phân quyền nhân viên và xuất báo cáo. Cần kiểm thử giao dịch SQL và tài liệu cấu hình.\n\nCách phối hợp: thống nhất phạm vi qua đề xuất, xác nhận hợp đồng và ký quỹ từng mốc trước khi thực hiện. Cập nhật tiến độ hai lần mỗi tuần. Bàn giao kèm tài liệu, tệp nguồn và hướng dẫn sử dụng trong phạm vi đã chốt.\n\nTôi đã rà soát phạm vi và đề xuất hai mốc có tiêu chí nghiệm thu riêng. Báo giá gồm phần việc được giao, tài liệu bàn giao và các vòng phản hồi trong phạm vi hợp đồng.","Currency":"VND","Price":24000000,"FeeRate":0.10,"DeliveryDays":28,"AcceptancePolicy":"Giá cố định theo mốc. Chỉ bắt đầu sau đủ xác nhận và bảo đảm mốc đầu. Client nghiệm thu hoặc yêu cầu sửa; quá 7 ngày chỉ nhắc. Không tự nghiệm thu. Phân chia sau phí theo tỷ trọng đội hình đã xác nhận.","ProductRights":"Client được sử dụng sản phẩm sau khi thanh toán đầy đủ phạm vi được nghiệm thu. Việc đưa sản phẩm/tài liệu Client vào Portfolio công khai cần chấp thuận riêng của Client.","Members":[{"UserId":6,"ProposalId":7,"Name":"Nguyễn Khánh Linh","Role":"Backend Developer","Weight":24000000}],"Milestones":[{"Title":"Thống nhất phương án và bàn giao bản đầu","Amount":9600000,"DueDay":14,"AcceptanceCriteria":"Hoàn tất danh sách yêu cầu, bản nháp có thể kiểm tra và ghi nhận phản hồi bằng văn bản."},{"Title":"Hoàn thiện và bàn giao phạm vi còn lại","Amount":14400000,"DueDay":28,"AcceptanceCriteria":"Sản phẩm đáp ứng tiêu chí trong hợp đồng; bàn giao tệp nguồn, tài liệu sử dụng và danh sách các mục đã đối chiếu."}]}', N'BECF1EA344D9F4A49FD27A3712FE38B0F999DCD0CF3E2E6F1833216543AD5C6A', CAST(24000000 AS Decimal(18, 0)), CAST(0.1000 AS Decimal(6, 4)), 28, CAST(N'2026-10-20T05:44:10.253' AS DateTime))
GO
INSERT [dbo].[ContractVersions] ([Id], [ContractId], [VersionNumber], [SnapshotJson], [Hash], [Price], [FeeRate], [DeliveryDays], [CreatedAtUtc]) VALUES (2, 2, 1, N'{"ProjectTitle":"Cổng bán hàng B2B Mộc Việt — hợp đồng độc lập","Scope":"Phát triển giao diện đặt hàng và API xử lý đơn theo hai hợp đồng độc lập. Hai phạm vi có tài liệu API chung; mỗi hợp đồng có mốc, xác nhận và ký quỹ riêng.\n\nCách phối hợp: thống nhất phạm vi qua đề xuất, xác nhận hợp đồng và ký quỹ từng mốc trước khi thực hiện. Cập nhật tiến độ hai lần mỗi tuần. Bàn giao kèm tài liệu, tệp nguồn và hướng dẫn sử dụng trong phạm vi đã chốt.\n\nTôi đã rà soát phạm vi và đề xuất hai mốc có tiêu chí nghiệm thu riêng. Báo giá gồm phần việc được giao, tài liệu bàn giao và các vòng phản hồi trong phạm vi hợp đồng.","Currency":"VND","Price":35000000,"FeeRate":0.10,"DeliveryDays":40,"AcceptancePolicy":"Giá cố định theo mốc. Chỉ bắt đầu sau đủ xác nhận và bảo đảm mốc đầu. Client nghiệm thu hoặc yêu cầu sửa; quá 7 ngày chỉ nhắc. Không tự nghiệm thu. Phân chia sau phí theo tỷ trọng đội hình đã xác nhận.","ProductRights":"Client được sử dụng sản phẩm sau khi thanh toán đầy đủ phạm vi được nghiệm thu. Việc đưa sản phẩm/tài liệu Client vào Portfolio công khai cần chấp thuận riêng của Client.","Members":[{"UserId":5,"ProposalId":8,"Name":"Hoàng Đức Minh","Role":"Frontend Developer","Weight":35000000}],"Milestones":[{"Title":"Thống nhất phương án và bàn giao bản đầu","Amount":14000000,"DueDay":20,"AcceptanceCriteria":"Hoàn tất danh sách yêu cầu, bản nháp có thể kiểm tra và ghi nhận phản hồi bằng văn bản."},{"Title":"Hoàn thiện và bàn giao phạm vi còn lại","Amount":21000000,"DueDay":40,"AcceptanceCriteria":"Sản phẩm đáp ứng tiêu chí trong hợp đồng; bàn giao tệp nguồn, tài liệu sử dụng và danh sách các mục đã đối chiếu."}]}', N'9983FCD2ACBF13D6279BE59B06583916459CE7FA96EB5A4AE821B9CA61D98B22', CAST(35000000 AS Decimal(18, 0)), CAST(0.1000 AS Decimal(6, 4)), 40, CAST(N'2026-10-20T05:44:10.893' AS DateTime))
