INSERT [dbo].[ContractVersions] ([Id], [ContractId], [VersionNumber], [SnapshotJson], [Hash], [Price], [FeeRate], [DeliveryDays], [CreatedAtUtc]) VALUES (4, 4, 1, N'{"ProjectTitle":"Cổng đặt lịch An Nhiên — triển khai theo đội hình","Scope":"Nhóm thiết kế và phát triển quy trình đặt lịch ba bước, khu vực quản trị lịch trống và thông báo xác nhận. Cần thống nhất các trạng thái lỗi và phân quyền trước khi bàn giao.\n\nCách phối hợp: thống nhất phạm vi qua đề xuất, xác nhận hợp đồng và ký quỹ từng mốc trước khi thực hiện. Cập nhật tiến độ hai lần mỗi tuần. Bàn giao kèm tài liệu, tệp nguồn và hướng dẫn sử dụng trong phạm vi đã chốt.\n\nNhóm đề xuất phân việc theo từng vai trò, cập nhật tiến độ tập trung và bàn giao theo hai mốc có tiêu chí rõ ràng. Trưởng nhóm điều phối phản hồi; mỗi thành viên xác nhận phạm vi và tỷ trọng trước khi ký quỹ.","Currency":"VND","Price":72000000,"FeeRate":0.10,"DeliveryDays":42,"AcceptancePolicy":"Giá cố định theo mốc. Chỉ bắt đầu sau đủ xác nhận và bảo đảm mốc đầu. Client nghiệm thu hoặc yêu cầu sửa; quá 7 ngày chỉ nhắc. Không tự nghiệm thu. Phân chia sau phí theo tỷ trọng đội hình đã xác nhận.","ProductRights":"Client được sử dụng sản phẩm sau khi thanh toán đầy đủ phạm vi được nghiệm thu. Việc đưa sản phẩm/tài liệu Client vào Portfolio công khai cần chấp thuận riêng của Client.","Members":[{"UserId":5,"ProposalId":10,"Name":"Hoàng Đức Minh","Role":"Frontend Developer","Weight":24000000},{"UserId":6,"ProposalId":11,"Name":"Nguyễn Khánh Linh","Role":"Backend Developer","Weight":28000000},{"UserId":7,"ProposalId":12,"Name":"Phạm Thu Trang","Role":"UI/UX Designer","Weight":20000000}],"Milestones":[{"Title":"Thống nhất phương án và bàn giao bản đầu","Amount":28800000,"DueDay":21,"AcceptanceCriteria":"Hoàn tất danh sách yêu cầu, bản nháp có thể kiểm tra và ghi nhận phản hồi bằng văn bản."},{"Title":"Hoàn thiện và bàn giao phạm vi còn lại","Amount":43200000,"DueDay":42,"AcceptanceCriteria":"Sản phẩm đáp ứng tiêu chí trong hợp đồng; bàn giao tệp