INSERT [dbo].[ContractVersions] ([Id], [ContractId], [VersionNumber], [SnapshotJson], [Hash], [Price], [FeeRate], [DeliveryDays], [CreatedAtUtc]) VALUES (5, 5, 1, N'{"ProjectTitle":"Dashboard doanh thu cửa hàng — chờ nghiệm thu bản đầu","Scope":"Tổng hợp doanh thu theo ngày, sản phẩm và chi nhánh. Bản đầu gồm dữ liệu mẫu đã đối chiếu, bảng định nghĩa chỉ số và giao diện báo cáo.\n\nCách phối hợp: thống nhất phạm vi qua đề xuất, xác nhận hợp đồng và ký quỹ từng mốc trước khi thực hiện. Cập nhật tiến độ hai lần mỗi tuần. Bàn giao kèm tài liệu, tệp nguồn và hướng dẫn sử dụng trong phạm vi đã chốt.\n\nTôi đã rà soát phạm vi và đề xuất hai mốc có tiêu chí nghiệm thu riêng. Báo giá gồm phần việc được giao, tài liệu bàn giao và các vòng phản hồi trong phạm vi hợp đồng.","Currency":"VND","Price":20000000,"FeeRate":0.10,"DeliveryDays":20,"AcceptancePolicy":"Giá cố định theo mốc. Chỉ bắt đầu sau đủ xác nhận và bảo đảm mốc đầu. Client nghiệm thu hoặc yêu cầu sửa; quá 7 ngày chỉ nhắc. Không tự nghiệm thu. Phân chia sau phí theo tỷ trọng đội hình đã xác nhận.","ProductRights":"Client được sử dụng sản phẩm sau khi thanh toán đầy đủ phạm vi được nghiệm thu. Việc đưa sản phẩm/tài liệu Client vào Portfolio công khai cần chấp thuận riêng của Client.","Members":[{"UserId":8,"ProposalId":13,"Name":"Vũ Thanh Hải","Role":"Data Analyst","Weight":20000000}],"Milestones":[{"Title":"Thống nhất phương án và bàn giao bản đầu","Amount":8000000,"DueDay":10,"AcceptanceCriteria":"Hoàn tất danh sách yêu cầu, bản nháp có thể kiểm tra và ghi nhận phản hồi bằng văn bản."},{"Title":"Hoàn thiện và bàn giao phạm vi còn lại","Amount":12000000,"DueDay":20,"AcceptanceCriteria":"Sản phẩm đáp ứng tiêu chí trong hợp đồng; bàn giao tệp nguồn, tài liệu sử dụng và danh sách các mục đã đối chiếu."}]}', N'C176E33446A6348C3BED34A23110FAA1141F61CA192DBCA8FE487FD2729EAB82', CAST(20000000 AS Decimal(18, 0)), CAST(0.1000 AS Decimal(6, 4)), 20, CAST(N'2026-10-20T05:44:12.970' AS DateTime))
