INSERT [dbo].[FreelancerProfiles] ([Id], [UserAccountId], [CoreRole], [Bio], [IsAvailable], [UpdatedAtUtc], [IsPublic], [Industry], [Location], [YearsExperience], [MinimumProjectBudget], [CoreSkillTrackId]) VALUES (1, 5, N'Frontend Developer', N'Tập trung vào frontend developer. Làm rõ yêu cầu trước khi báo giá, cập nhật tiến độ theo tuần và bàn giao kèm hướng dẫn sử dụng. Thiết kế và triển khai các màn hình chọn dịch vụ, khung giờ và xác nhận đặt lịch trên máy tính và điện thoại.', 1, CAST(N'2026-10-20T05:44:08.840' AS DateTime), 1, N'Công nghệ thông tin', N'Đà Nẵng', 5, CAST(8000000.00 AS Decimal(18, 2)), 2)
GO
INSERT [dbo].[FreelancerProfiles] ([Id], [UserAccountId], [CoreRole], [Bio], [IsAvailable], [UpdatedAtUtc], [IsPublic], [Industry], [Location], [YearsExperience], [MinimumProjectBudget], [CoreSkillTrackId]) VALUES (2, 6, N'Backend Developer', N'Tập trung vào backend developer. Làm rõ yêu cầu trước khi báo giá, cập nhật tiến độ theo tuần và bàn giao kèm hướng dẫn sử dụng. Xây dựng API quản lý dịch vụ, lịch hẹn, người dùng và phân quyền theo vai trò với C# và SQL Server.', 1, CAST(N'2026-10-20T05:44:09.083' AS DateTime), 1, N'Công nghệ thông tin', N'Hà Nội', 6, CAST(12000000.00 AS Decimal(18, 2)), 1)
GO
INSERT [dbo].[FreelancerProfiles] ([Id], [UserAccountId], [CoreRole], [Bio], [IsAvailable], [UpdatedAtUtc], [IsPublic], [Industry], [Location], [YearsExperience], [MinimumProjectBudget], [CoreSkillTrackId]) VALUES (3, 7, N'UI/UX Designer', N'Tập trung vào ui/ux designer. Làm rõ yêu cầu trước khi báo giá, cập nhật tiến độ theo tuần và bàn giao kèm hướng dẫn sử dụng. Lập sơ đồ hành trình, wireframe và bộ giao diện cho khách hàng đặt lịch khám hoặc tư vấn.', 1, CAST(N'2026-10-20T05:44:09.143' AS DateTime), 1, N'Thiết kế & sáng tạo', N'Hà Nội', 4, CAST(6000000.00 AS Decimal(18, 2)), 4)
