INSERT [dbo].[FreelancerProfiles] ([Id], [UserAccountId], [CoreRole], [Bio], [IsAvailable], [UpdatedAtUtc], [IsPublic], [Industry], [Location], [YearsExperience], [MinimumProjectBudget], [CoreSkillTrackId]) VALUES (6, 10, N'Content Writer', N'Tập trung vào content writer. Làm rõ yêu cầu trước khi báo giá, cập nhật tiến độ theo tuần và bàn giao kèm hướng dẫn sử dụng. Xây dựng giọng điệu thương hiệu, cấu trúc bài viết và nội dung giới thiệu từng dòng cà phê.', 1, CAST(N'2026-10-20T05:44:09.220' AS DateTime), 1, N'Nội dung & biên dịch', N'Hà Nội', 4, CAST(4000000.00 AS Decimal(18, 2)), 8)
