INSERT [dbo].[FreelancerProfiles] ([Id], [UserAccountId], [CoreRole], [Bio], [IsAvailable], [UpdatedAtUtc], [IsPublic], [Industry], [Location], [YearsExperience], [MinimumProjectBudget], [CoreSkillTrackId]) VALUES (7, 11, N'Graphic Designer', N'Tập trung vào graphic designer. Làm rõ yêu cầu trước khi báo giá, cập nhật tiến độ theo tuần và bàn giao kèm hướng dẫn sử dụng. Phát triển logo, màu sắc, hệ chữ và bộ ứng dụng trên bao bì, thực đơn, bài đăng mạng xã hội.', 1, CAST(N'2026-10-20T05:44:09.227' AS DateTime), 1, N'Thiết kế & sáng tạo', N'TP. Hồ Chí Minh', 6, CAST(6000000.00 AS Decimal(18, 2)), 5)
GO
INSERT [dbo].[FreelancerProfiles] ([Id], [UserAccountId], [CoreRole], [Bio], [IsAvailable], [UpdatedAtUtc], [IsPublic], [Industry], [Location], [YearsExperience], [MinimumProjectBudget], [CoreSkillTrackId]) VALUES (8, 12, N'Biên dịch Anh – Việt', N'Tập trung vào biên dịch anh – việt. Làm rõ yêu cầu trước khi báo giá, cập nhật tiến độ theo tuần và bàn giao kèm hướng dẫn sử dụng. Dịch mô tả sản phẩm, thống nhất thuật ngữ vật liệu và hiệu đính theo ngữ cảnh bán lẻ.', 1, CAST(N'2026-10-20T05:44:09.237' AS DateTime), 1, N'Nội dung & biên dịch', N'Huế', 7, CAST(4000000.00 AS Decimal(18, 2)), 9)
GO
INSERT [dbo].[FreelancerProfiles] ([Id], [UserAccountId], [CoreRole], [Bio], [IsAvailable], [UpdatedAtUtc], [IsPublic], [Industry], [Location], [YearsExperience], [MinimumProjectBudget], [CoreSkillTrackId]) VALUES (9, 13, N'QA Engineer', N'Tập trung vào qa engineer. Làm rõ yêu cầu trước khi báo giá, cập nhật tiến độ theo tuần và bàn giao kèm hướng dẫn sử dụng. Lập test case cho giỏ hàng, đặt hàng, phân quyền và đối chiếu dữ liệu giữa giao diện với hệ thống.', 1, CAST(N'2026-10-20T05:44:09.247' AS DateTime), 1, N'Công nghệ thông tin', N'Đà Nẵng', 4, CAST(6000000.00 AS Decimal(18, 2)), NULL)
GO
INSERT [dbo].[FreelancerProfiles] ([Id], [UserAccountId], [CoreRole], [Bio], [IsAvailable], [UpdatedAtUtc], [IsPublic], [Industry], [Location], [YearsExperience], [MinimumProjectBudget], [CoreSkillTrackId]) VALUES (10, 14, N'Project Manager', N'Tập trung vào project manager. Làm rõ yêu cầu trước khi báo giá, cập nhật tiến độ theo tuần và bàn giao kèm hướng dẫn sử dụng. Làm rõ phạm vi, phụ thuộc, trách nhiệm thành viên và kế hoạch nghiệm thu theo tuần.', 1, CAST(N'2026-10-20T05:44:09.257' AS DateTime), 1, N'Kinh doanh & tư vấn', N'Hà Nội', 8, CAST(10000000.00 AS Decimal(18, 2)), 11)
